\begin{definition}[$C([0,T];X)$]
\label{def:continuous-time-banach-space}
\dcref{ch5:5.9-def-4}
\group{Bochner Spaces}
The space
$$C([0, T]; X)$$
comprises all continuous functions $\mathbf{u} : [0, T] \to X$ with
$$\|\mathbf{u}\|_{C([0,T];X)} := \max_{0 \le t \le T} \|\mathbf{u}(t)\| < \infty.$$
\end{definition}

